package com.commercecore.order;
import com.commercecore.promotion.*;import com.commercecore.shipping.ShippingServiceLevel;import com.commercecore.user.UserAccount;import jakarta.persistence.*;import java.math.*;import java.time.Instant;import java.util.*;
@Entity@Table(name="orders")public class CustomerOrder{
 @Id@GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(name="order_number",nullable=false,unique=true,length=32)private String orderNumber;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="customer_id",nullable=false)private UserAccount customer;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private OrderStatus status;
 @Column(name="checkout_idempotency_key",nullable=false,length=160)private String idempotencyKey;@Column(name="checkout_request_fingerprint",nullable=false,length=64)private String requestFingerprint;
 @Column(nullable=false,precision=19,scale=2)private BigDecimal subtotal;@Column(name="merchandise_discount",nullable=false,precision=19,scale=2)private BigDecimal merchandiseDiscount;@Column(name="discounted_merchandise_total",nullable=false,precision=19,scale=2)private BigDecimal discountedMerchandiseTotal;@Column(name="shipping_fee_before_discount",nullable=false,precision=19,scale=2)private BigDecimal shippingFeeBeforeDiscount;@Column(name="shipping_discount",nullable=false,precision=19,scale=2)private BigDecimal shippingDiscount;@Column(name="shipping_fee",nullable=false,precision=19,scale=2)private BigDecimal shippingFee;@Column(name="tax_amount",nullable=false,precision=19,scale=2)private BigDecimal taxAmount;@Column(name="grand_total",nullable=false,precision=19,scale=2)private BigDecimal grandTotal;
 @ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="promotion_id")private Promotion promotion;@Column(name="promotion_code",length=64)private String promotionCode;@Column(name="promotion_name",length=160)private String promotionName;@Enumerated(EnumType.STRING)@Column(name="promotion_type",length=24)private PromotionType promotionType;@Column(name="promotion_discount",precision=19,scale=2)private BigDecimal promotionDiscount;
 @Enumerated(EnumType.STRING)@Column(name="shipping_service_level",nullable=false,length=16)private ShippingServiceLevel shippingServiceLevel;@Column(name="shipping_estimated_days",nullable=false)private int shippingEstimatedDays;@Column(name="reservation_expires_at",nullable=false)private Instant reservationExpiresAt;@Column(name="created_at",nullable=false,updatable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@Version@Column(nullable=false)private long version;
 protected CustomerOrder(){}public CustomerOrder(String number,UserAccount customer,String key,String fingerprint,BigDecimal subtotal,BigDecimal discount,BigDecimal merchandiseTotal,BigDecimal shippingBefore,BigDecimal shippingDiscount,BigDecimal shippingFee,BigDecimal tax,BigDecimal grand,Promotion promotion,BigDecimal promotionDiscount,ShippingServiceLevel level,int estimatedDays,Instant expiresAt){this.orderNumber=required(number,32);this.customer=Objects.requireNonNull(customer);this.idempotencyKey=required(key,160);this.requestFingerprint=required(fingerprint,64);this.subtotal=money(subtotal);this.merchandiseDiscount=money(discount);this.discountedMerchandiseTotal=money(merchandiseTotal);this.shippingFeeBeforeDiscount=money(shippingBefore);this.shippingDiscount=money(shippingDiscount);this.shippingFee=money(shippingFee);this.taxAmount=money(tax);this.grandTotal=money(grand);this.promotion=promotion;if(promotion!=null){promotionCode=promotion.getCode();promotionName=promotion.getName();promotionType=promotion.getType();this.promotionDiscount=money(promotionDiscount);}this.shippingServiceLevel=Objects.requireNonNull(level);if(estimatedDays<1)throw new IllegalArgumentException();shippingEstimatedDays=estimatedDays;this.reservationExpiresAt=Objects.requireNonNull(expiresAt);status=OrderStatus.PENDING;validateMoney();}
 private void validateMoney(){if(List.of(subtotal,merchandiseDiscount,discountedMerchandiseTotal,shippingFeeBeforeDiscount,shippingDiscount,shippingFee,taxAmount,grandTotal).stream().anyMatch(v->v.signum()<0)||discountedMerchandiseTotal.compareTo(subtotal.subtract(merchandiseDiscount))!=0||shippingFee.compareTo(shippingFeeBeforeDiscount.subtract(shippingDiscount))!=0||grandTotal.compareTo(discountedMerchandiseTotal.add(shippingFee).add(taxAmount))!=0)throw new IllegalArgumentException("invalid order totals");}
 public void transition(OrderStatus target){boolean valid=status==OrderStatus.PENDING&&(target==OrderStatus.CONFIRMED||target==OrderStatus.CANCELLED)||status==OrderStatus.CONFIRMED&&(target==OrderStatus.PROCESSING||target==OrderStatus.CANCELLED)||status==OrderStatus.PROCESSING&&(target==OrderStatus.SHIPPED||target==OrderStatus.CANCELLED)||status==OrderStatus.SHIPPED&&target==OrderStatus.DELIVERED;if(!valid)throw new IllegalStateException("invalid order transition");status=target;}
 @PrePersist void create(){Instant now=Instant.now();createdAt=now;updatedAt=now;}@PreUpdate void touch(){updatedAt=Instant.now();}private static BigDecimal money(BigDecimal v){return Objects.requireNonNull(v).setScale(2,RoundingMode.HALF_UP);}private static String required(String v,int max){if(v==null||v.isBlank()||v.trim().length()>max)throw new IllegalArgumentException();return v.trim();}
 public UUID getId(){return id;}public String getOrderNumber(){return orderNumber;}public UserAccount getCustomer(){return customer;}public OrderStatus getStatus(){return status;}public String getIdempotencyKey(){return idempotencyKey;}public String getRequestFingerprint(){return requestFingerprint;}public BigDecimal getSubtotal(){return subtotal;}public BigDecimal getMerchandiseDiscount(){return merchandiseDiscount;}public BigDecimal getDiscountedMerchandiseTotal(){return discountedMerchandiseTotal;}public BigDecimal getShippingFeeBeforeDiscount(){return shippingFeeBeforeDiscount;}public BigDecimal getShippingDiscount(){return shippingDiscount;}public BigDecimal getShippingFee(){return shippingFee;}public BigDecimal getTaxAmount(){return taxAmount;}public BigDecimal getGrandTotal(){return grandTotal;}public Promotion getPromotion(){return promotion;}public String getPromotionCode(){return promotionCode;}public String getPromotionName(){return promotionName;}public PromotionType getPromotionType(){return promotionType;}public BigDecimal getPromotionDiscount(){return promotionDiscount;}public ShippingServiceLevel getShippingServiceLevel(){return shippingServiceLevel;}public int getShippingEstimatedDays(){return shippingEstimatedDays;}public Instant getReservationExpiresAt(){return reservationExpiresAt;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}
}
